'@
# id=full record bytes from the 100% reference save
$ReferenceTable = @'








406=0396010000435B01000000009644FE7F572C000000000000000000000300000000000000000000D016950C




501=03F5010000435B0100000000B7E108605FE3000000000000000000000300000700000000000000D016D10C

504=03F8010000435B01000000002328FE7F2F2F000000000000000000000300000500000000000000D016950C
505=03F9010000435B0100000000E02BFE7FCF2E000000000000000000000300000600000000000000D016150C
506=03FA010000435B0100000000183300601833000000000000000000000300000500000000000000D0161B0C

510=03FE010000435A01000000008C2D00608C2D000000000000000000000300000100000000000000D016150C
513=0301020000435A01000000006A9000606A90000000000000000000000300000600000000000000D016B10B
601=0359020000435B0100000000519500605195000000000000000000000300000300000000000000D016B10B
602=035A020000435B01000000003B44FD7FFA45000000000000000000000300000000000000000000D016150C












703=03BF02000040000100000000528F0060528F0000000000000000000003000001000000000000001421E00B
704=03C00200004000010000000094B6FE7FF1200000000000000000000003000000000000000000001421150C




709=03C5020000400001000000007356FE7F8E2A0000000000000000000003000000000000000000001421A10B




714=03CA0200004000010000000068FFFC7FDB4C0000000000000000000003000000000000000000001421050C
715=03CB020000400001000000000F6801600F680100000000000000000003000000000000000000001421F00B

717=03CD02000040000200000000294000602940000000000000000000000300000000000000AAB90060AAB90000000000000000000003000A00000000000000000E000000



721=03D10200004000010000000061F3006061F30000000000000000000003000001000000000000000A000000
























