823=033703000040000100000000D7630360C8560000000000000000000003000001000000000000001421E10B
'@

$Challenges = @{}
$ChallengeList = @()
foreach ($line in ($ChallengeTable -split "`r?`n")) {
    if (-not $line.Trim()) { continue }
    $p = $line.Split('|')
    $c = [pscustomobject]@{ Id = [int]$p[0]; Name = $p[1]; Best = [int]$p[2]; LowerIsBetter = ($p[3] -eq '1') }
    $Challenges[$c.Id] = $c
    $ChallengeList += $c
}
$Reference = @{}
foreach ($line in ($ReferenceTable -split "`r?`n")) {
    if (-not $line.Trim()) { continue }
    $p = $line.Split('=')
    $hex = $p[1].Trim()
    $bytes = New-Object byte[] ($hex.Length / 2)
    for ($i = 0; $i -lt $bytes.Length; $i++) { $bytes[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16) }
    $Reference[[int]$p[0]] = $bytes
}
$OtherIds = @(102, 201, 204, 302, 303, 503, 124, 224, 424, 524, 817, 404, 901, 902, 903)   # trainings, dev tests, PS4-only
$BackupRoot = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'ArkhamKnight_SaveBackup'

function Test-KnownId([int]$id) { $Challenges.ContainsKey($id) -or ($OtherIds -contains $id) }

function Read-Records([byte[]]$b) {
    $limit = [Math]::Min($b.Length - 16, 0x40000)
    for ($p = 0; $p -lt $limit; $p++) {
        if ($b[$p + 4] -ne 3) { continue }
        $count = [BitConverter]::ToInt32($b, $p)
        if ($count -lt 1 -or $count -gt 400) { continue }
        if (-not (Test-KnownId ([BitConverter]::ToInt32($b, $p + 5)))) { continue }
        $list = New-Object System.Collections.Generic.List[object]
        $pos = $p + 4
        $ok = $true
        for ($i = 0; $i -lt $count; $i++) {
            if ($pos + 19 -gt $b.Length -or $b[$pos] -ne 3) { $ok = $false; break }
            $id = [BitConverter]::ToInt32($b, $pos + 1)
            if (-not (Test-KnownId $id)) { $ok = $false; break }
            if ($b[$pos + 7] -gt 8) { $ok = $false; break }
            $len = 19 + 24 * $b[$pos + 7]
            $rec = New-Object byte[] $len
            [Array]::Copy($b, $pos, $rec, 0, $len)
            $list.Add([pscustomobject]@{ Id = $id; Bytes = $rec })
            $pos += $len
        }
        if ($ok) { return [pscustomobject]@{ CountOffset = $p; End = $pos; Records = $list } }
    }
    throw "Could not find the AR challenge list in this save."
}

function Get-RecordState($rec) {
    if (-not $rec) { return [pscustomobject]@{ Status = 'Locked'; Stars = 0; Best = 0 } }
    $n = $rec.Bytes[7]
    if ($n -eq 0) { return [pscustomobject]@{ Status = 'Unlocked'; Stars = 0; Best = 0 } }
    $stars = -1; $best = 0
    for ($e = 0; $e -lt $n; $e++) {
        $s = $rec.Bytes[28 + 24 * $e]
        if ($s -gt $stars) { $stars = $s; $best = [BitConverter]::ToInt32($rec.Bytes, 16 + 24 * $e) }
    }
    return [pscustomobject]@{ Status = 'Played'; Stars = $stars; Best = $best }
}

# Existing entry (mutated in place): raise best to the 3-star goal and set stars; packed field is left as the game wrote it
function Set-EntryThreeStars([byte[]]$rec, [int]$e, $c) {
    $o = 8 + 24 * $e
    $old = [BitConverter]::ToInt32($rec, $o + 8)
    $best = $c.Best
    if ($old -gt 0) { if ($c.LowerIsBetter) { $best = [Math]::Min($old, $best) } else { $best = [Math]::Max($old, $best) } }
    [BitConverter]::GetBytes([int]$best).CopyTo($rec, $o + 8)
    $rec[$o + 20] = 3
}

# The reference entry for the challenge's default character/vehicle (byte +22 == 0)
function Get-DefaultEntry([byte[]]$ref) {
    $idx = 0
    for ($e = 0; $e -lt $ref[7]; $e++) { if ($ref[8 + 24 * $e + 22] -eq 0) { $idx = $e; break } }
    $entry = New-Object byte[] 24
    [Array]::Copy($ref, 8 + 24 * $idx, $entry, 0, 24)
    $entry[22] = 0
    return , $entry
}

function Get-UpdatedSave([byte[]]$b, [int[]]$ids) {
    $info = Read-Records $b
    $recs = $info.Records
    foreach ($id in $ids) {
        $c = $Challenges[$id]
        $ex = $null
        foreach ($r in $recs) { if ($r.Id -eq $id) { $ex = $r; break } }
        if ($ex -and $ex.Bytes[7] -gt 0) {
            for ($e = 0; $e -lt $ex.Bytes[7]; $e++) { Set-EntryThreeStars $ex.Bytes $e $c }
        }
        elseif ($ex) {
            # Unlocked: keep the id/flags/tail the game wrote, add one default-character entry
            $s = $ex.Bytes
            $rec = New-Object byte[] 43
            [Array]::Copy($s, 0, $rec, 0, 7)
            $rec[7] = 1
            (Get-DefaultEntry $Reference[$id]).CopyTo($rec, 8)
            [Array]::Copy($s, 8, $rec, 32, 11)
            $ex.Bytes = $rec
        }
        else {
            # Locked (experimental): reference id/flags/tail with one default-character entry
            $ref = $Reference[$id]
            $rec = New-Object byte[] 43
            [Array]::Copy($ref, 0, $rec, 0, 7)
            $rec[7] = 1
            (Get-DefaultEntry $ref).CopyTo($rec, 8)
            [Array]::Copy($ref, $ref.Length - 11, $rec, 32, 11)
            $recs.Add([pscustomobject]@{ Id = $id; Bytes = $rec })
        }
    }
    $ms = New-Object IO.MemoryStream
    $ms.Write($b, 0, $info.CountOffset)
    $ms.Write([BitConverter]::GetBytes([int]$recs.Count), 0, 4)
    foreach ($r in $recs) { $ms.Write($r.Bytes, 0, $r.Bytes.Length) }
    $ms.Write($b, $info.End, $b.Length - $info.End)
    $out = $ms.ToArray()
    # Header u32 at 0x0C is the byte size of the section holding the challenge list;
    # the game crashes on load if it doesn't match after records grow or shrink
    $delta = $out.Length - $b.Length
    [BitConverter]::GetBytes([int]([BitConverter]::ToInt32($b, 0x0C) + $delta)).CopyTo($out, 0x0C)
    if ($out.Length -gt $b.Length) {
        for ($i = $b.Length; $i -lt $out.Length; $i++) { if ($out[$i] -ne 0) { throw "Not enough free space at the end of the save." } }
        $trim = New-Object byte[] $b.Length
        [Array]::Copy($out, $trim, $b.Length)
        $out = $trim
    }
    elseif ($out.Length -lt $b.Length) {
        $pad = New-Object byte[] $b.Length
        [Array]::Copy($out, $pad, $out.Length)
        $out = $pad
    }
    return , $out
}

# WayneTech upgrade points, found by spending points (70 -> 67 -> 68). After the "- Total" text of
# the combat score help: u32 N, N x u32, then u32 points, u32, u32, u32 K, K x u32 training ids.
# N is 16 in most saves but 14 early in a new game, so the offset moves; the training ids validate it.
function Find-PointsOffset([byte[]]$b) {
    $s = [Text.Encoding]::ASCII.GetString($b, 0, [Math]::Min($b.Length, 0x40000))
    $t = $s.IndexOf("- Total`0")
    if ($t -lt 0) { return -1 }
    $n = [BitConverter]::ToInt32($b, $t + 8)
    if ($n -lt 1 -or $n -gt 64) { return -1 }
    $po = $t + 12 + 4 * $n
    $k = [BitConverter]::ToInt32($b, $po + 12)
    if ($k -lt 1 -or $k -gt 32) { return -1 }
    for ($i = 0; $i -lt $k; $i++) { if (-not (Test-KnownId ([BitConverter]::ToInt32($b, $po + 16 + 4 * $i)))) { return -1 } }
    return $po
}

function Find-Saves {
    $steam = $null
    try { $steam = (Get-ItemProperty 'HKCU:\Software\Valve\Steam' -Name SteamPath).SteamPath -replace '/', '\' } catch {}
    if (-not $steam) { $steam = 'C:\Program Files (x86)\Steam' }
    $files = Get-ChildItem (Join-Path $steam 'userdata') -Directory -ErrorAction SilentlyContinue | ForEach-Object {
        Get-ChildItem (Join-Path $_.FullName '208650\remote') -Filter 'BAK1Save*.sgd' -File -ErrorAction SilentlyContinue
    }
    # The game rotates 3 files per slot; the newest one is the live save
    $files | Where-Object { $_.Name -match '^BAK1Save(\d)x\d\.sgd$' } |
        Group-Object { $_.DirectoryName + '|' + ($_.Name -replace '^BAK1Save(\d)x\d\.sgd$', '$1') } |
        ForEach-Object {
            $f = $_.Group | Sort-Object LastWriteTime -Descending | Select-Object -First 1
            $slot = [int]($f.Name -replace '^BAK1Save(\d)x\d\.sgd$', '$1') + 1
            [pscustomobject]@{ File = $f.FullName; Label = ('Slot {0}  -  last saved {1:dd MMM yyyy HH:mm}  ({2})' -f $slot, $f.LastWriteTime, $f.Name); Time = $f.LastWriteTime }
        } | Sort-Object Time -Descending
}

function Backup-SaveFolder([string]$folder, [string]$suffix) {
    $dst = Join-Path $BackupRoot ((Get-Date -Format 'yyyy-MM-dd_HHmmss') + $suffix)
    New-Item -ItemType Directory -Force $dst | Out-Null
    Copy-Item (Join-Path $folder '*') $dst -Force
    return $dst
}

# One untouched copy per Steam account, made the first time the tool sees it
function Save-OriginalBackup([string]$folder) {
    $sid = Split-Path (Split-Path (Split-Path $folder -Parent) -Parent) -Leaf
    if (Get-ChildItem $BackupRoot -Directory -Filter "*_ORIGINAL_$sid" -ErrorAction SilentlyContinue) { return $null }
    return Backup-SaveFolder $folder "_ORIGINAL_$sid"
}

function Test-GameRunning { [bool](Get-Process BatmanAK -ErrorAction SilentlyContinue) }

function Format-Best($c, [int]$v) {
    if ($v -le 0) { return '' }
    if ($c.LowerIsBetter) { return ('{0}:{1:00}.{2:00}' -f [Math]::Floor($v / 6000), [Math]::Floor(($v % 6000) / 100), ($v % 100)) }
    return $v.ToString('N0')
}

if ($SelfTest) {
    $missing = @($ChallengeList | Where-Object { -not $Reference.ContainsKey($_.Id) })
    "Challenges: $($ChallengeList.Count), reference records: $($Reference.Count), missing reference: $($missing.Count)"
    foreach ($s in Find-Saves) {
        $b = [IO.File]::ReadAllBytes($s.File)
        $info = Read-Records $b
        $states = @{}
        foreach ($c in $ChallengeList) { $states[$c.Id] = (Get-RecordState ($info.Records | Where-Object { $_.Id -eq $c.Id } | Select-Object -First 1)).Status }
        $all = @($ChallengeList | ForEach-Object { $_.Id })
        $new = Get-UpdatedSave $b $all
        $after = Read-Records $new
        $bad = @($all | Where-Object { $k = $_; (Get-RecordState ($after.Records | Where-Object { $_.Id -eq $k } | Select-Object -First 1)).Stars -ne 3 })
        $po = Find-PointsOffset $b
        if ($po -ge 0) { "  WayneTech points: $([BitConverter]::ToInt32($b, $po)) (at 0x$('{0:X}' -f $po))" } else { "  WayneTech points: not found" }
        '{0}: records={1} at 0x{2:X}, played={3}, unlocked={4}, locked={5}; dry-run on all -> {6}' -f $s.Label, $info.Records.Count, $info.CountOffset,
            @($states.Values | Where-Object { $_ -eq 'Played' }).Count, @($states.Values | Where-Object { $_ -eq 'Unlocked' }).Count, @($states.Values | Where-Object { $_ -eq 'Locked' }).Count,
            $(if ($bad.Count -eq 0 -and $new.Length -eq $b.Length) { "OK ($($after.Records.Count) records)" } else { "FAILED ($($bad -join ','))" })
    }
    return
}

