    $col = New-Object System.Windows.Forms.DataGridViewTextBoxColumn
    $col.HeaderText = $h[0]; $col.FillWeight = $h[1]; $col.ReadOnly = $true
    [void]$grid.Columns.Add($col)
}
$grid.Columns[4].DefaultCellStyle.ForeColor = [System.Drawing.Color]::DarkGoldenrod
$grid.Columns[4].DefaultCellStyle.Font = New-Object System.Drawing.Font('Segoe UI Symbol', 10)

