$script:saves = @()
function Load-Grid {
    $grid.Rows.Clear()
    if ($combo.SelectedIndex -lt 0) { return }
    $file = $script:saves[$combo.SelectedIndex].File
    $bytes = [IO.File]::ReadAllBytes($file)
    $po = Find-PointsOffset $bytes
    if ($po -ge 0) {
        $numPts.Value = [Math]::Max(0, [Math]::Min(999, [BitConverter]::ToInt32($bytes, $po)))
        $numPts.Enabled = $true; $btnPts.Enabled = $true
        $lblPtsNote.Text = 'Unspent points shown on the upgrade screen.'
    }
    else {
        $numPts.Value = 0; $numPts.Enabled = $false; $btnPts.Enabled = $false
        $lblPtsNote.Text = 'Points not found in this save (older save format).'
    }
    try { $info = Read-Records $bytes }
    catch { $status.Text = "Could not read this save: $($_.Exception.Message)"; return }
    $total = 0
    foreach ($c in $ChallengeList) {
        $rec = $null
        foreach ($r in $info.Records) { if ($r.Id -eq $c.Id) { $rec = $r; break } }
        $st = Get-RecordState $rec
        $n = [Math]::Max(0, [Math]::Min(3, $st.Stars)); $total += $n
        $i = $grid.Rows.Add($false, $c.Id, $c.Name, $st.Status, ($star * $n + $hollow * (3 - $n)), (Format-Best $c $st.Best))
        if ($st.Status -eq 'Locked') { $grid.Rows[$i].DefaultCellStyle.ForeColor = [System.Drawing.Color]::Gray }
        $grid.Rows[$i].Tag = $st.Status
    }
    $status.Text = "Stars in this save: $total.  Try a few challenges first, then load the game. Locked (grey) ones are experimental.`n$script:backupNote"
}

function Refresh-Saves {
    $script:saves = @(Find-Saves)
    $script:backupNote = "Backups: $BackupRoot"
    foreach ($folder in ($script:saves | ForEach-Object { Split-Path $_.File } | Sort-Object -Unique)) {
        try { $made = Save-OriginalBackup $folder; if ($made) { $script:backupNote = "Original saves backed up to $made" } }
        catch { $script:backupNote = "Could not make the original backup: $($_.Exception.Message)" }
    }
    $combo.Items.Clear()
    foreach ($s in $script:saves) { [void]$combo.Items.Add($s.Label) }
    if ($combo.Items.Count -gt 0) { $combo.SelectedIndex = 0 } else { $status.Text = 'No Arkham Knight saves found in Steam userdata.' }
}

$combo.Add_SelectedIndexChanged({ Load-Grid })
$btnReload.Add_Click({ Refresh-Saves })
$btnClear.Add_Click({ foreach ($r in $grid.Rows) { $r.Cells[0].Value = $false } })
$btnTickUnlocked.Add_Click({
    foreach ($r in $grid.Rows) { $r.Cells[0].Value = ($r.Tag -ne 'Locked' -and $r.Cells[4].Value -ne ($star * 3)) }
})
$btnOpen.Add_Click({ New-Item -ItemType Directory -Force $BackupRoot | Out-Null; Start-Process explorer.exe $BackupRoot })
$btnPts.Add_Click({
    if (Test-GameRunning) { [void][System.Windows.Forms.MessageBox]::Show('Arkham Knight is running. Close it first.', 'Game running', 'OK', 'Warning'); return }
    if ($combo.SelectedIndex -lt 0) { return }
    try {
        $file = $script:saves[$combo.SelectedIndex].File
        $b = [IO.File]::ReadAllBytes($file)
        $po = Find-PointsOffset $b
        if ($po -lt 0) { throw 'WayneTech points not found in this save.' }
        $old = [BitConverter]::ToInt32($b, $po)
        $bk = Backup-SaveFolder (Split-Path $file) ''
        [BitConverter]::GetBytes([int]$numPts.Value).CopyTo($b, $po)
        [IO.File]::WriteAllBytes($file, $b)
        Load-Grid
        $status.Text = "WayneTech points: $old -> $($numPts.Value). Backup: $bk`nIf Steam shows a Cloud conflict when you start the game, choose the LOCAL files."
    }
    catch { [void][System.Windows.Forms.MessageBox]::Show($_.Exception.Message, 'Error', 'OK', 'Error') }
})
$btnBackup.Add_Click({
    if ($combo.SelectedIndex -lt 0) { return }
    $bk = Backup-SaveFolder (Split-Path $script:saves[$combo.SelectedIndex].File) '_manual'
    $status.Text = "Backed up all save slots to $bk"
})

$btnApply.Add_Click({
    $grid.EndEdit()
    if (Test-GameRunning) { [void][System.Windows.Forms.MessageBox]::Show('Arkham Knight is running. Close it first.', 'Game running', 'OK', 'Warning'); return }
    $ids = @(); $locked = @()
    foreach ($r in $grid.Rows) { if ($r.Cells[0].Value -eq $true) { $ids += [int]$r.Cells[1].Value; if ($r.Tag -eq 'Locked') { $locked += $r.Cells[2].Value } } }
    if ($ids.Count -eq 0) { $status.Text = 'Nothing ticked.'; return }
    if ($locked.Count -gt 0) {
        $msg = "You ticked $($locked.Count) locked challenge(s):`n`n" + (($locked | Select-Object -First 10) -join "`n") + "`n`nThese get a record copied from a real 100% save. Your saves are backed up first; if the game won't load, use 'Restore a backup'. Continue?"
        if ([System.Windows.Forms.MessageBox]::Show($msg, 'Locked challenges', 'YesNo', 'Warning') -ne 'Yes') { return }
    }
    try {
        $file = $script:saves[$combo.SelectedIndex].File
        $b = [IO.File]::ReadAllBytes($file)
        $out = Get-UpdatedSave $b $ids
        $bk = Backup-SaveFolder (Split-Path $file) ''
        [IO.File]::WriteAllBytes($file, $out)
        Load-Grid
        $status.Text = "Done: $($ids.Count) challenge(s) set to 3 stars. Backup: $bk`nIf Steam shows a Cloud conflict when you start the game, choose the LOCAL files."
    }
    catch { [void][System.Windows.Forms.MessageBox]::Show($_.Exception.Message, 'Error', 'OK', 'Error') }
})

$btnRestore.Add_Click({
    if (Test-GameRunning) { [void][System.Windows.Forms.MessageBox]::Show('Arkham Knight is running. Close it first.', 'Game running', 'OK', 'Warning'); return }
    if ($combo.SelectedIndex -lt 0) { return }
    New-Item -ItemType Directory -Force $BackupRoot | Out-Null
    $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
    $dlg.Description = 'Pick a backup folder to restore (they are named by date and time)'
    $dlg.SelectedPath = $BackupRoot
    if ($dlg.ShowDialog() -ne 'OK') { return }
    $src = $dlg.SelectedPath
    if (-not (Get-ChildItem $src -Filter 'BAK1Save*.sgd' -File)) { [void][System.Windows.Forms.MessageBox]::Show('That folder has no Arkham Knight save files.', 'Restore', 'OK', 'Warning'); return }
    $dest = Split-Path $script:saves[$combo.SelectedIndex].File
    if ([System.Windows.Forms.MessageBox]::Show("Replace all saves in`n$dest`nwith the backup from`n$src ?`n`n(Your current saves are backed up first.)", 'Restore', 'YesNo', 'Question') -ne 'Yes') { return }
    $bk = Backup-SaveFolder $dest '_before_restore'
    Copy-Item (Join-Path $src '*') $dest -Force
    Refresh-Saves
    $status.Text = "Restored from $src. (Previous state saved to $bk)"
})

$form.Add_Shown({ Refresh-Saves })
[void]$form.ShowDialog()
